2	 * Resolves the request's `Actor` for a given org slug, or throws
3	 * `unauthorized` / `forbidden`. Every Server Action starts here.
4	 *
5	 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
6	 * this module is the seam between "there is an HTTP request with a cookie"
7	 * and the rest of the app, which knows nothing about requests.
8	 */
9	import { getSessionPrincipal } from "@/lib/session";
10	import { assertOrgScope } from "@/lib/tenant";
11	import { findOrgById } from "@/server/repositories/organization-repository";
12	import { resolveActorForOrg } from "@/server/services/session-service";
13	import type { OrgId } from "@/types/common";
14	import type { Actor } from "@/types/member";
15	
16	/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
17	export class UnauthorizedError extends Error {
18	  readonly code = "unauthorized" as const;
19	
20	  constructor(message = "Sign in to continue.") {
21	    super(message);
22	    this.name = "UnauthorizedError";
23	  }
24	}
