26	/** Thrown when the session is valid but has no membership in the target org. */
27	export class NoMembershipError extends Error {
28	  readonly code = "forbidden" as const;
29	
30	  constructor(readonly orgSlug: string) {
31	    super(`You are not a member of "${orgSlug}".`);
32	    this.name = "NoMembershipError";
33	  }
