2	 * Recomputes the usage counters that every `LimitCheck` compares against.
3	 *
4	 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
5	 */
6	import { getPlanLimits } from "@/config/plan-limits";
7	import { emit, subscribe } from "@/lib/event-bus";
8	import { assertOrgScope } from "@/lib/tenant";
9	import * as orgRepo from "@/server/repositories/organization-repository";
10	import * as usageRepo from "@/server/repositories/usage-repository";
11	import { toIsoTimestamp } from "@/types/common";
12	import type { OrgId } from "@/types/common";
13	import type { Unsubscribe } from "@/types/event";
14	import type { Actor } from "@/types/member";
15	import type { OrganizationUsage } from "@/types/organization";
16	
17	/** Fraction of a quota at which the "approaching limit" event fires. */
18	const WARN_THRESHOLD = 0.9;
19	
20	export async function getUsage(
21	  actor: Actor,
22	  orgId: OrgId,
23	): Promise<OrganizationUsage> {
24	  assertOrgScope(actor, orgId);
25	  return usageRepo.getUsage(orgId);
26	}
27	
28	/**
29	 * Full recount from the source tables. Called by the rollup job and by every
30	 * event that could have moved a counter — after recounting, the seat and
31	 * project totals are checked against the plan so a breach surfaces as an
32	 * event rather than waiting for the next write to be rejected.
33	 */
34	export async function recomputeUsage(
35	  orgId: OrgId,
36	): Promise<OrganizationUsage> {
37	  const usage = await usageRepo.recomputeUsage(orgId);
38	  const org = await orgRepo.findOrgById(orgId);
39	  if (!org) return usage;
40	
41	  const limits = getPlanLimits(org.plan);
42	
43	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
44	    await emit("billing.limit_exceeded", {
45	      orgId,
46	      actorId: null,
47	      occurredAt: toIsoTimestamp(new Date()),
48	      resource: "seats",
49	      limit: limits.seats,
50	      used: usage.seatsUsed,
51	    });
52	  }
53	
54	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
55	    await emit("billing.limit_exceeded", {
56	      orgId,
57	      actorId: null,
58	      occurredAt: toIsoTimestamp(new Date()),
59	      resource: "projects",
60	      limit: limits.projects,
61	      used: usage.projectsUsed,
62	    });
63	  }
64	
65	  return usage;
66	}
67	
68	/**
69	 * Every event that changes a counted resource nudges the cache. The deltas are
70	 * cheap; the periodic rollup is what corrects any drift they accumulate.
71	 */
72	export function registerUsageListeners(): Unsubscribe {
73	  const offs: Unsubscribe[] = [
74	    subscribe("issue.created", async (payload) => {
75	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
76	    }),
77	    subscribe("issue.archived", async (payload) => {
78	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
79	    }),
80	    subscribe("project.created", async (payload) => {
81	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
82	    }),
83	    subscribe("project.archived", async (payload) => {
84	      await usageRepo.incrementUsage(payload.orgId, {
85	        projectsUsed: -1,
